package com.bidx.servlet;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.*;import com.bidx.service.*;import com.bidx.repository.*;import com.bidx.model.*;
class DashboardServletImpl extends BaseServlet {private final AuctionService auctions=new AuctionService();private final BidService bids=new BidService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{User u=user(r);r.setAttribute("myAuctions",auctions.mine(u.id));r.setAttribute("myBids",bids.mine(u.id));r.setAttribute("active",auctions.browse(null,null,"ACTIVE","ending"));view(r,p,"user/dashboard");}}
class MyAuctionsServletImpl extends BaseServlet {private final AuctionService s=new AuctionService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("auctions",s.mine(user(r).id));view(r,p,"user/my-auctions");}}
class MyBidsServletImpl extends BaseServlet {private final BidService s=new BidService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("bids",s.mine(user(r).id));view(r,p,"user/my-bids");}}
class WatchlistServletImpl extends BaseServlet {private final WatchlistRepository w=new WatchlistRepository();private final AuctionService a=new AuctionService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("ids",w.forUser(user(r).id));r.setAttribute("auctions",a.browse(null,null,null,"ending"));view(r,p,"user/watchlist");}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{w.toggle(user(r).id,r.getParameter("auctionId"));p.sendRedirect(r.getContextPath()+"/watchlist");}}
